"use client";

import { Box, Notification, NotificationProps } from '@mantine/core';

function Wrapper(props: NotificationProps) {
  return (
    <Box maw={400} mx="auto">
      <Notification onClose={() => {}} {...props} />
    </Box>
  );
}
const RendynExampleComponent = Wrapper;
export function RendynExample() { return <RendynExampleComponent loading={false} withCloseButton={true} withBorder={false} color={"blue"} radius={"md"} title={"We notify you that"} children={"You are now obligated to give a star to Mantine project on GitHub"} />; }

"use client";

import { CheckIcon, XIcon } from '@phosphor-icons/react';

import { Notification } from '@mantine/core';

function Demo() {
  const xIcon = <XIcon size={20} />;
  const checkIcon = <CheckIcon size={20} />;

  return (
    <>
      <Notification icon={xIcon} color="red" title="Bummer!">
        Something went wrong
      </Notification>
      <Notification icon={checkIcon} color="teal" title="All good!" mt="md">
        Everything is fine
      </Notification>
    </>
  );
}
const RendynExampleComponent = Demo;
export function RendynExample() { return <RendynExampleComponent  />; }

"use client";

import { CheckIcon } from '@phosphor-icons/react';

import { Box, Notification } from '@mantine/core';

function Demo(props: any) {
  return (
    <Box maw={400} mx="auto">
      <Notification title="Please wait" loading withCloseButton={false} {...props}>
        The application is trying to reconnect to the server
      </Notification>
      <Notification mt="md" icon={<CheckIcon size={18} />} title="We notify you that" {...props}>
        You are now obligated to give a star to Mantine project on GitHub
      </Notification>
    </Box>
  );
}
const RendynExampleComponent = Demo;
export function RendynExample() { return <RendynExampleComponent  />; }

